def cases():return json.loads(json.dumps(CASES))
@lru_cache(maxsize=1)
def _rows():return {r['case']['key']:r for r in json.loads(FIXTURE.read_text(encoding='utf-8'))['rows']}
def expected(case):return list(_rows()[case['key']]['expected'])
def production(case):
    from PyFLASH.stats import modified_anderson
    return [None if not math.isfinite(v) else float(v) for v in modified_anderson(case['values'])]
def equal(a,b):
    return len(a)==len(b) and all((x is None and y is None) or (x is not None and y is not None
        and math.isclose(x,y,rel_tol=1e-9,abs_tol=0 if i else 1e-12)) for i,(x,y) in enumerate(zip(a,b)))
def check_identity():
    fixture=json.loads(FIXTURE.read_text(encoding='utf-8'))
    if hashlib.sha256(Path(__file__).read_bytes()).hexdigest()!=fixture['reference_code_sha256']:raise ValueError('Normality reference source changed')
    if hashlib.sha256(SOURCE.read_bytes()).hexdigest()!=fixture['published_source']['sha256']:raise ValueError('Published R normality kernel changed')
    if cases()!=[r['case'] for r in fixture['rows']]:raise ValueError('Frozen normality cases changed')
    return fixture
def execute(output):
    fixture=check_identity()
    return execute_queries(fixture['queries'],output,name='unchanged-published-nortest-normality')
